"use client";

import Link from "next/link";
import { useCallback, useEffect, useState, type FormEvent } from "react";
import { ArrowLeftRight, BookOpen, Boxes, CheckCircle2, ClipboardCheck, FilePlus2, PackageSearch, Pencil, Plus, RefreshCw, Search, Settings, ShieldCheck, Truck, Warehouse, XCircle } from "lucide-react";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { PageContainer, PageHeader } from "@/components/shared/page-header";

export type InventorySection = "dashboard" | "items" | "locations" | "vendors" | "on-hand" | "transactions" | "requests" | "counts" | "approvals" | "movement" | "stock-card" | "configuration";
type Permissions = string[];
type Item = { id: string; code: string; name: string; unit: string; category: string | null; active: boolean; minimumStock: string; reorderPoint: string | null; defaultUnitCost: string | null; movingAverageCost: string | null; mainLocation: { code: string } | null; balances?: Array<{ location: { code: string }; quantityOnHand: string; availableQuantity: string; movingAverageCost: string | null; inventoryValue: string | null }> };
type Location = { id: string; code: string; name: string; plant: string | null; warehouse: string | null; zone: string | null; rack: string | null; shelf: string | null; bin: string | null; active: boolean; balances?: Array<{ stockItem: Item; quantityOnHand: string; inventoryValue: string | null }> };
type Vendor = { id: string; code: string; name: string; email: string | null; phone: string | null; preferredVendor: boolean; active: boolean; rating: { calculatedScore: string | null; manualScore: string | null; finalScore: string | null; ratingGrade: string | null } | null; contacts?: Array<{ name: string; email: string | null; primaryContact: boolean }> };
type Document = { id: string; documentType: string; documentNumber: string; documentDate: string; status: string; purpose: string | null; requesterName: string; lines: Array<{ id: string; stockItem: Item; sourceLocation: Location | null; destinationLocation: Location | null; requestedQuantity: string; approvedQuantity: string | null; unit: string; unitCost: string | null; totalAmount: string | null; sourceReceiptDocumentNumber?: string | null }> };
type Movement = { id: string; movementType: string; documentNumber: string | null; sourceReceiptDocumentNumber?: string | null; postedAt: string; stockItem: Item; location: Location; sourceLocation: Location | null; destinationLocation: Location | null; quantityIn: string; quantityOut: string; quantityBefore: string; quantityAfter: string; unitCost: string | null; amountIn: string | null; amountOut: string | null };
type Approval = { id: string; referenceNumber: string; title: string; status: string; requestedAt: string; requestedByName: string; assignedRole: string; waitingMinutes: number };

const labels: Record<string, string> = { ISSUE: "Issue", RECEIPT: "Receipt", TRANSFER: "Transfer", POSTED: "Posted", DRAFT: "Draft", RETURNED: "Returned", REJECTED: "Rejected", PENDING_MAINTENANCE_MANAGER: "Pending Maintenance Manager", PENDING_WAREHOUSE_MANAGER: "Pending Warehouse Manager", PENDING_PLANT_MANAGER: "Pending Plant Manager", COUNTING: "Counting", ADJUST_IN: "Adjust In", ADJUST_OUT: "Adjust Out", TRANSFER_IN: "Transfer In", TRANSFER_OUT: "Transfer Out", MAINTENANCE_MANAGER: "Maintenance Manager", WAREHOUSE_MANAGER: "Warehouse Manager", PLANT_MANAGER: "Plant Manager" };
const label = (value: string) => labels[value] ?? value.replaceAll("_", " ").toLowerCase().replace(/(^|\s)\S/g, (letter) => letter.toUpperCase());
const date = (value: string | null | undefined) => value ? new Date(value).toLocaleString("en-GB", { dateStyle: "medium", timeStyle: "short" }) : "—";
const money = (value: string | null | undefined) => value === null || value === undefined ? "Restricted" : Number(value).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const statusTone = (status: string) => status === "POSTED" || status === "APPROVED" ? "border-emerald-200 bg-emerald-50 text-emerald-800" : status === "REJECTED" ? "border-red-200 bg-red-50 text-red-800" : status === "RETURNED" ? "border-amber-200 bg-amber-50 text-amber-900" : "border-blue-200 bg-blue-50 text-blue-800";

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> { const response = await fetch(url, init); const body = await response.json().catch(() => ({})); if (!response.ok) throw new Error(body.error || "Unable to complete the request"); return body as T; }
function value(form: HTMLFormElement, name: string) { return String(new FormData(form).get(name) ?? "").trim(); }
function nullable(form: HTMLFormElement, name: string) { return value(form, name) || null; }
function jsonInit(body: unknown, method = "POST"): RequestInit { return { method, headers: { "content-type": "application/json" }, body: JSON.stringify(body) }; }

function State({ message, retry }: { message: string; retry?: () => void }) { return <div className="grid min-h-48 place-items-center rounded-2xl border border-dashed bg-white p-6 text-center text-sm text-slate-500"><div><PackageSearch className="mx-auto mb-3 size-9 text-slate-400" /><p>{message}</p>{retry && <Button variant="outline" className="mt-4" onClick={retry}><RefreshCw className="size-4" /> Try again</Button>}</div></div>; }
function Status({ value }: { value: string }) { return <Badge className={statusTone(value)}>{label(value)}</Badge>; }
function TableShell({ children }: { children: React.ReactNode }) { return <div className="overflow-x-auto rounded-2xl border bg-white shadow-sm"><table className="w-full min-w-[52rem] text-left text-sm">{children}</table></div>; }
function Field({ name, label: fieldLabel, type = "text", required = false, placeholder, defaultValue, children }: { name: string; label: string; type?: string; required?: boolean; placeholder?: string; defaultValue?: string; children?: React.ReactNode }) { return <div><Label htmlFor={name}>{fieldLabel}</Label>{children ?? <Input id={name} name={name} type={type} required={required} placeholder={placeholder} defaultValue={defaultValue} className="mt-1 min-h-10 bg-white" />}</div>; }

function Dashboard({ permissions }: { permissions: Permissions }) {
  const [data, setData] = useState<{ metrics: { activeItems: number; locations: number; vendors: number; pendingApprovals: number; pendingCounts: number; inventoryValue: string | null; quantityOnHand: string }; lowStock: Array<{ id: string; code: string; name: string; quantityOnHand: string; reorderPoint: string }> } | null>(null);
  const load = () => void requestJson<typeof data>("/api/inventory/dashboard").then(setData).catch((error) => toast.error(error.message));
  useEffect(load, []);
  if (!data) return <State message="Loading inventory dashboard…" retry={load} />;
  const metrics = [{ label: "Active stock items", value: data.metrics.activeItems, href: "/inventory/items", icon: PackageSearch }, { label: "Storage locations", value: data.metrics.locations, href: "/inventory/locations", icon: Warehouse }, { label: "Vendors", value: data.metrics.vendors, href: "/inventory/vendors", icon: Truck }, { label: "Inventory value", value: money(data.metrics.inventoryValue), href: "/inventory/on-hand", icon: BookOpen }, { label: "Pending approvals", value: data.metrics.pendingApprovals, href: "/inventory/approvals", icon: ShieldCheck }, { label: "Stock counts waiting", value: data.metrics.pendingCounts, href: "/inventory/counts", icon: ClipboardCheck }];
  return <div className="space-y-6"><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{metrics.map((metric) => { const Icon = metric.icon; return <Link key={metric.label} href={metric.href}><Card className="h-full border-slate-200 transition hover:-translate-y-0.5 hover:border-blue-300 hover:shadow-md"><CardContent className="flex items-center gap-4 p-5"><span className="grid size-11 place-items-center rounded-xl bg-blue-50 text-blue-700"><Icon className="size-5" /></span><div><p className="text-xs font-medium text-slate-500">{metric.label}</p><p className="mt-1 text-2xl font-bold tabular-nums text-slate-950">{metric.value}</p></div></CardContent></Card></Link>; })}</div><div className="grid gap-6 lg:grid-cols-[1.4fr_1fr]"><Card><CardHeader><CardTitle className="flex items-center gap-2 text-base"><PackageSearch className="size-5 text-amber-600" />Low stock watchlist</CardTitle></CardHeader><CardContent>{data.lowStock.length ? <div className="divide-y">{data.lowStock.map((item) => <div key={item.id} className="flex items-center justify-between gap-4 py-3"><div><strong className="font-mono text-sm">{item.code}</strong><p className="text-xs text-slate-500">{item.name}</p></div><div className="text-right"><p className="font-bold text-amber-700">{item.quantityOnHand}</p><p className="text-xs text-slate-500">Reorder at {item.reorderPoint}</p></div></div>)}</div> : <p className="py-6 text-sm text-slate-500">No items are below their reorder point.</p>}</CardContent></Card><Card><CardHeader><CardTitle className="text-base">Inventory controls</CardTitle></CardHeader><CardContent className="grid gap-2"><Link className="rounded-xl border px-4 py-3 text-sm font-semibold hover:bg-blue-50" href="/inventory/requests"><FilePlus2 className="mr-2 inline size-4 text-blue-700" />Create Issue, Receipt or Transfer</Link><Link className="rounded-xl border px-4 py-3 text-sm font-semibold hover:bg-blue-50" href="/inventory/stock-card"><BookOpen className="mr-2 inline size-4 text-blue-700" />Open Stock Card report</Link>{permissions.includes("INVENTORY_CONFIG_MANAGE") && <Link className="rounded-xl border px-4 py-3 text-sm font-semibold hover:bg-blue-50" href="/inventory/configuration"><Settings className="mr-2 inline size-4 text-blue-700" />Review configuration</Link>}</CardContent></Card></div></div>;
}

function ItemWorkspace({ permissions }: { permissions: Permissions }) {
  const [items, setItems] = useState<Item[]>([]); const [query, setQuery] = useState(""); const [showForm, setShowForm] = useState(false); const canEdit = permissions.includes("INVENTORY_STOCK_ITEM_MANAGE");
  const load = useCallback(() => void requestJson<{ items: Item[] }>(`/api/inventory/items?q=${encodeURIComponent(query)}&pageSize=100&active=all`).then((data) => setItems(data.items)).catch((error) => toast.error(error.message)), [query]);
  useEffect(() => { const timer = window.setTimeout(load, 200); return () => window.clearTimeout(timer); }, [load]);
  async function create(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = event.currentTarget; try { await requestJson("/api/inventory/items", jsonInit({ code: value(form, "code"), name: value(form, "name"), unit: value(form, "unit"), category: nullable(form, "category"), manufacturer: nullable(form, "manufacturer"), partNumber: nullable(form, "partNumber"), barcode: nullable(form, "barcode"), minimumStock: value(form, "minimumStock") || "0", reorderPoint: nullable(form, "reorderPoint"), maximumStock: nullable(form, "maximumStock"), defaultUnitCost: value(form, "defaultUnitCost") || "0", mainLocationId: nullable(form, "mainLocationId"), criticalSparePart: form.elements.namedItem("criticalSparePart") instanceof HTMLInputElement && (form.elements.namedItem("criticalSparePart") as HTMLInputElement).checked, active: true, remark: nullable(form, "remark")})); toast.success("Stock item created"); form.reset(); setShowForm(false); load(); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to create stock item"); } }
  return <div className="space-y-4"><div className="flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="pointer-events-none absolute left-3 top-3 size-4 text-slate-400" /><Input className="min-h-11 bg-white pl-9" placeholder="Search code, name, category…" value={query} onChange={(event) => setQuery(event.target.value)} /></div>{canEdit && <Button className="min-h-11" onClick={() => setShowForm((value) => !value)}><Plus className="size-4" />New Stock Item</Button>}</div>{showForm && <Card><CardHeader><CardTitle className="text-base">New stock item</CardTitle></CardHeader><CardContent><form className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4" onSubmit={create}><Field name="code" label="Stock Code" required /><Field name="name" label="Stock Name" required /><Field name="unit" label="Unit" required defaultValue="EA" /><Field name="category" label="Category" /><Field name="manufacturer" label="Manufacturer" /><Field name="partNumber" label="Part Number" /><Field name="barcode" label="Barcode / QR" /><Field name="minimumStock" label="Minimum Stock" type="number" defaultValue="0" /><Field name="reorderPoint" label="Reorder Point" type="number" /><Field name="maximumStock" label="Maximum Stock" type="number" /><Field name="defaultUnitCost" label="Default Unit Cost" type="number" defaultValue="0" /><div className="flex items-end gap-2"><input id="criticalSparePart" name="criticalSparePart" type="checkbox" className="mb-3 size-4" /><Label htmlFor="criticalSparePart" className="mb-2">Critical spare part</Label></div><div className="flex items-end gap-2 sm:col-span-2 lg:col-span-4"><Button type="submit">Save draft item</Button><Button type="button" variant="ghost" onClick={() => setShowForm(false)}>Cancel</Button></div></form></CardContent></Card>}{items.length === 0 ? <State message="No stock items found." /> : <TableShell><thead className="border-b bg-slate-50 text-xs text-slate-500"><tr>{["Code", "Item", "Category", "Balance by location", "Moving average", "Status", "Main location"].map((head) => <th key={head} className="px-4 py-3 font-semibold">{head}</th>)}</tr></thead><tbody className="divide-y">{items.map((item) => <tr key={item.id} className="hover:bg-blue-50/40"><td className="px-4 py-4"><Link className="font-mono font-bold text-blue-700" href={`/inventory/items/${item.id}`}>{item.code}</Link></td><td className="px-4 py-4"><strong>{item.name}</strong><span className="block text-xs text-slate-500">{item.unit}</span></td><td className="px-4 py-4 text-slate-600">{item.category ?? "—"}</td><td className="px-4 py-4">{item.balances?.length ? <div className="space-y-1">{item.balances.map((balance) => <div key={balance.location.code} className="flex justify-between gap-4 text-xs"><span>{balance.location.code}</span><strong>{balance.availableQuantity}</strong></div>)}</div> : <span className="text-slate-400">No balance</span>}</td><td className="px-4 py-4 tabular-nums">{money(item.movingAverageCost)}</td><td className="px-4 py-4"><Status value={item.active ? "ACTIVE" : "INACTIVE"} /></td><td className="px-4 py-4 text-slate-600">{item.mainLocation?.code ?? "—"}</td></tr>)}</tbody></TableShell>}</div>;
}

function LocationWorkspace({ permissions }: { permissions: Permissions }) {
  const [locations, setLocations] = useState<Location[]>([]); const [query, setQuery] = useState(""); const [showForm, setShowForm] = useState(false); const canEdit = permissions.includes("INVENTORY_LOCATION_MANAGE");
  const load = useCallback(() => void requestJson<{ locations: Location[] }>(`/api/inventory/locations?q=${encodeURIComponent(query)}&pageSize=100&active=all`).then((data) => setLocations(data.locations)).catch((error) => toast.error(error.message)), [query]); useEffect(() => { const timer = window.setTimeout(load, 200); return () => window.clearTimeout(timer); }, [load]);
  async function create(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = event.currentTarget; try { await requestJson("/api/inventory/locations", jsonInit({ code: value(form, "code"), name: value(form, "name"), plant: nullable(form, "plant"), warehouse: nullable(form, "warehouse"), zone: nullable(form, "zone"), rack: nullable(form, "rack"), shelf: nullable(form, "shelf"), bin: nullable(form, "bin"), description: nullable(form, "description"), active: true })); toast.success("Storage location created"); form.reset(); setShowForm(false); load(); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to create location"); } }
  return <div className="space-y-4"><div className="flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="pointer-events-none absolute left-3 top-3 size-4 text-slate-400" /><Input className="min-h-11 bg-white pl-9" placeholder="Search location code, plant, warehouse…" value={query} onChange={(event) => setQuery(event.target.value)} /></div>{canEdit && <Button className="min-h-11" onClick={() => setShowForm((value) => !value)}><Plus className="size-4" />New Location</Button>}</div>{showForm && <Card><CardHeader><CardTitle className="text-base">New storage location</CardTitle></CardHeader><CardContent><form className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4" onSubmit={create}><Field name="code" label="Location Code" required /><Field name="name" label="Location Name" required /><Field name="plant" label="Plant" /><Field name="warehouse" label="Warehouse" /><Field name="zone" label="Zone" /><Field name="rack" label="Rack" /><Field name="shelf" label="Shelf" /><Field name="bin" label="Bin" /><div className="flex items-end gap-2 sm:col-span-2 lg:col-span-4"><Button type="submit">Save location</Button><Button type="button" variant="ghost" onClick={() => setShowForm(false)}>Cancel</Button></div></form></CardContent></Card>}{locations.length === 0 ? <State message="No storage locations found." /> : <TableShell><thead className="border-b bg-slate-50 text-xs text-slate-500"><tr>{["Code", "Location", "Hierarchy", "Balances", "Status"].map((head) => <th key={head} className="px-4 py-3 font-semibold">{head}</th>)}</tr></thead><tbody className="divide-y">{locations.map((location) => <tr key={location.id} className="hover:bg-blue-50/40"><td className="px-4 py-4 font-mono font-bold text-blue-700">{location.code}</td><td className="px-4 py-4"><strong>{location.name}</strong><span className="block text-xs text-slate-500">{location.plant ?? "No plant"}</span></td><td className="px-4 py-4 text-xs text-slate-600">{[location.warehouse, location.zone, location.rack, location.shelf, location.bin].filter(Boolean).join(" / ") || "—"}</td><td className="px-4 py-4">{location.balances?.length ?? 0} item balances</td><td className="px-4 py-4"><Status value={location.active ? "ACTIVE" : "INACTIVE"} /></td></tr>)}</tbody></TableShell>}</div>;
}

function VendorWorkspace({ permissions }: { permissions: Permissions }) {
  const [vendors, setVendors] = useState<Vendor[]>([]); const [query, setQuery] = useState(""); const [showForm, setShowForm] = useState(false); const canEdit = permissions.includes("INVENTORY_VENDOR_MANAGE");
  const load = useCallback(() => void requestJson<{ vendors: Vendor[] }>(`/api/inventory/vendors?q=${encodeURIComponent(query)}&pageSize=100&active=all`).then((data) => setVendors(data.vendors)).catch((error) => toast.error(error.message)), [query]); useEffect(() => { const timer = window.setTimeout(load, 200); return () => window.clearTimeout(timer); }, [load]);
  async function create(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = event.currentTarget; try { await requestJson("/api/inventory/vendors", jsonInit({ code: value(form, "code"), name: value(form, "name"), taxId: nullable(form, "taxId"), phone: nullable(form, "phone"), email: nullable(form, "email"), country: nullable(form, "country"), province: nullable(form, "province"), paymentTerms: nullable(form, "paymentTerms"), deliveryTerms: nullable(form, "deliveryTerms"), leadTime: nullable(form, "leadTime"), preferredVendor: form.elements.namedItem("preferredVendor") instanceof HTMLInputElement && (form.elements.namedItem("preferredVendor") as HTMLInputElement).checked, active: true })); toast.success("Vendor created"); form.reset(); setShowForm(false); load(); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to create vendor"); } }
  return <div className="space-y-4"><div className="flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="pointer-events-none absolute left-3 top-3 size-4 text-slate-400" /><Input className="min-h-11 bg-white pl-9" placeholder="Search vendor code, name, email…" value={query} onChange={(event) => setQuery(event.target.value)} /></div>{canEdit && <Button className="min-h-11" onClick={() => setShowForm((value) => !value)}><Plus className="size-4" />New Vendor</Button>}</div>{showForm && <Card><CardHeader><CardTitle className="text-base">New vendor</CardTitle></CardHeader><CardContent><form className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4" onSubmit={create}><Field name="code" label="Vendor Code" required /><Field name="name" label="Vendor Name" required /><Field name="taxId" label="Tax ID" /><Field name="phone" label="Phone" /><Field name="email" label="Email" type="email" /><Field name="country" label="Country" /><Field name="province" label="Province" /><Field name="leadTime" label="Lead time (days)" type="number" /><div className="flex items-end gap-2"><input id="preferredVendor" name="preferredVendor" type="checkbox" className="mb-3 size-4" /><Label htmlFor="preferredVendor" className="mb-2">Preferred vendor</Label></div><div className="flex items-end gap-2 sm:col-span-2 lg:col-span-4"><Button type="submit">Save vendor</Button><Button type="button" variant="ghost" onClick={() => setShowForm(false)}>Cancel</Button></div></form></CardContent></Card>}{vendors.length === 0 ? <State message="No vendors found." /> : <TableShell><thead className="border-b bg-slate-50 text-xs text-slate-500"><tr>{["Vendor", "Contact", "Rating", "Preference", "Status", "Actions"].map((head) => <th key={head} className="px-4 py-3 font-semibold">{head}</th>)}</tr></thead><tbody className="divide-y">{vendors.map((vendor) => <tr key={vendor.id} className="hover:bg-blue-50/40"><td className="px-4 py-4"><Link href={`/inventory/vendors/${vendor.id}`} className="font-mono font-bold text-blue-700">{vendor.code}</Link><span className="block text-sm">{vendor.name}</span></td><td className="px-4 py-4 text-xs text-slate-600">{vendor.contacts?.[0]?.name ?? vendor.email ?? "—"}</td><td className="px-4 py-4">{vendor.rating?.finalScore ? <span className="font-bold">{vendor.rating.finalScore} <span className="text-xs text-slate-500">({vendor.rating.ratingGrade})</span></span> : <span className="text-slate-400">Not calculated</span>}</td><td className="px-4 py-4">{vendor.preferredVendor && <Badge className="border-blue-200 bg-blue-50 text-blue-800">Preferred</Badge>}</td><td className="px-4 py-4"><Status value={vendor.active ? "ACTIVE" : "INACTIVE"} /></td><td className="px-4 py-4"><Button asChild size="sm" variant="outline"><Link href={`/inventory/vendors/${vendor.id}`}><Pencil className="size-3.5" />Detail</Link></Button></td></tr>)}</tbody></TableShell>}</div>;
}

function ReferenceLoader({ children }: { children: (refs: { items: Item[]; locations: Location[]; vendors: Vendor[] }) => React.ReactNode }) {
  const [refs, setRefs] = useState<{ items: Item[]; locations: Location[]; vendors: Vendor[] } | null>(null); const [error, setError] = useState("");
  useEffect(() => { Promise.all([requestJson<{ items: Item[] }>("/api/inventory/items?pageSize=100&active=true"), requestJson<{ locations: Location[] }>("/api/inventory/locations?pageSize=100&active=true"), requestJson<{ vendors: Vendor[] }>("/api/inventory/vendors?pageSize=100&active=true")]).then(([items, locations, vendors]) => setRefs({ items: items.items, locations: locations.locations, vendors: vendors.vendors })).catch((cause) => setError(cause instanceof Error ? cause.message : "Unable to load references")); }, []);
  if (error) return <State message={error} />; if (!refs) return <State message="Loading inventory references…" />; return <>{children(refs)}</>;
}

function RequestWorkspace({ permissions }: { permissions: Permissions }) {
  const [documents, setDocuments] = useState<Document[]>([]); const [showForm, setShowForm] = useState(false); const canCreate = permissions.includes("INVENTORY_REQUEST_CREATE");
  const load = () => void requestJson<{ documents: Document[] }>("/api/inventory/documents?pageSize=100").then((data) => setDocuments(data.documents)).catch((error) => toast.error(error.message)); useEffect(load, []);
  return <ReferenceLoader>{(refs) => <div className="space-y-4"><div className="flex flex-wrap gap-2">{canCreate && <Button onClick={() => setShowForm((value) => !value)}><Plus className="size-4" />New inventory request</Button>}<Button variant="outline" onClick={load}><RefreshCw className="size-4" />Refresh</Button></div>{showForm && <RequestForm refs={refs} onSaved={() => { setShowForm(false); load(); }} />}{documents.length === 0 ? <State message="No inventory requests yet." /> : <TableShell><thead className="border-b bg-slate-50 text-xs text-slate-500"><tr>{["Document", "Type", "Lines", "Requester", "Date", "Status", "Action"].map((head) => <th key={head} className="px-4 py-3 font-semibold">{head}</th>)}</tr></thead><tbody className="divide-y">{documents.map((document) => <tr key={document.id} className="hover:bg-blue-50/40"><td className="px-4 py-4 font-mono font-bold text-blue-700">{document.documentNumber}</td><td className="px-4 py-4">{label(document.documentType)}</td><td className="px-4 py-4">{document.lines.length}</td><td className="px-4 py-4">{document.requesterName}</td><td className="px-4 py-4 text-xs text-slate-600">{date(document.documentDate)}</td><td className="px-4 py-4"><Status value={document.status} /></td><td className="px-4 py-4"><div className="flex flex-wrap gap-2">{["DRAFT", "RETURNED"].includes(document.status) && <Button size="sm" onClick={() => void requestJson(`/api/inventory/documents/${document.id}/actions`, jsonInit({ action: "SUBMIT" })).then(() => { toast.success("Submitted for approval"); load(); }).catch((error) => toast.error(error.message))}>Submit</Button>}<a className="rounded-md border px-2 py-1 text-xs font-semibold text-blue-700 hover:bg-blue-50" href={`/api/inventory/documents/${document.id}/print`} target="_blank" rel="noreferrer">Print</a>{permissions.includes("INVENTORY_POST") && document.status === "POSTED" && <Button size="sm" variant="destructive" onClick={() => { if (!window.confirm(`Reverse posted document ${document.documentNumber}?`)) return; void requestJson(`/api/inventory/documents/${document.id}/actions`, jsonInit({ action: "CANCEL" })).then(() => { toast.success("Document reversed"); load(); }).catch((error) => toast.error(error.message)); }}>Reverse</Button>}</div></td></tr>)}</tbody></TableShell>}</div>}</ReferenceLoader>;
}

function RequestForm({ refs, onSaved }: { refs: { items: Item[]; locations: Location[]; vendors: Vendor[] }; onSaved: () => void }) {
  type ReceiptSource = { id: string; documentNumber: string; documentDate: string; lineNumber: number; stockItem: { code: string; name: string }; destinationLocation: { code: string; name: string } | null; vendor: { code: string; name: string } | null; receivedQuantity: string; availableQuantity: string; unitCost: string | null };
  type DraftLine = { stockItemId: string; requestedQuantity: string; sourceLocationId: string; destinationLocationId: string; sourceReceiptLineId: string; vendorId: string; receiptAmount: string; expectedDeliveryDate: string; actualDeliveryDate: string; workOrderId: string; jobStepId: string; remark: string };
  const blankLine = (): DraftLine => ({ stockItemId: "", requestedQuantity: "1", sourceLocationId: "", destinationLocationId: "", sourceReceiptLineId: "", vendorId: "", receiptAmount: "", expectedDeliveryDate: "", actualDeliveryDate: "", workOrderId: "", jobStepId: "", remark: "" });
  const [type, setType] = useState<"ISSUE" | "RECEIPT" | "TRANSFER">("ISSUE");
  const [lines, setLines] = useState<DraftLine[]>([blankLine()]);
  const [receiptSources, setReceiptSources] = useState<Record<number, ReceiptSource[]>>({});
  const [sourceLoading, setSourceLoading] = useState<Record<number, boolean>>({});

  function updateLine(index: number, field: keyof DraftLine, next: string) { setLines((current) => current.map((line, lineIndex) => lineIndex === index ? { ...line, [field]: next } : line)); }
  async function loadReceiptSources(index: number, stockItemId: string, locationId: string, requestedType = type) {
    if (requestedType !== "ISSUE" || !stockItemId || !locationId) { setReceiptSources((current) => ({ ...current, [index]: [] })); return; }
    setSourceLoading((current) => ({ ...current, [index]: true }));
    try {
      const params = new URLSearchParams({ stockItemId, locationId });
      const result = await requestJson<{ receiptSources: ReceiptSource[] }>(`/api/inventory/receipt-sources?${params}`);
      setReceiptSources((current) => ({ ...current, [index]: result.receiptSources }));
    } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to load Receipt sources"); }
    finally { setSourceLoading((current) => ({ ...current, [index]: false })); }
  }
  async function save(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const form = event.currentTarget; const data = new FormData(form);
    try {
      const purpose = String(data.get("purpose") ?? "").trim(); if (!purpose) throw new Error("Purpose is required");
      const payloadLines = lines.map((line, index) => {
        const item = refs.items.find((candidate) => candidate.id === line.stockItemId);
        const requestedQuantity = String(data.get(`requestedQuantity-${index}`) ?? line.requestedQuantity).trim();
        if (!item) throw new Error("Select a stock item for every line");
        if (!requestedQuantity || Number(requestedQuantity) <= 0) throw new Error("Every line needs a positive quantity");
        const receiptAmount = String(data.get(`receiptAmount-${index}`) ?? line.receiptAmount).trim();
        if (type === "RECEIPT" && (!receiptAmount || Number(receiptAmount) < 0)) throw new Error("Every Receipt line needs an amount");
        if (type === "ISSUE" && !line.sourceReceiptLineId) throw new Error("Select a source Receipt for every Issue line");
        return { stockItemId: item.id, sourceLocationId: type === "RECEIPT" ? null : line.sourceLocationId || null, destinationLocationId: type === "ISSUE" ? null : line.destinationLocationId || null, requestedQuantity, unit: item.unit, receiptAmount: type === "RECEIPT" ? receiptAmount : undefined, sourceReceiptLineId: type === "ISSUE" ? line.sourceReceiptLineId || null : null, vendorId: type === "RECEIPT" ? line.vendorId || null : null, expectedDeliveryDate: String(data.get(`expectedDeliveryDate-${index}`) ?? line.expectedDeliveryDate).trim() || null, actualDeliveryDate: String(data.get(`actualDeliveryDate-${index}`) ?? line.actualDeliveryDate).trim() || null, workOrderId: String(data.get(`workOrderId-${index}`) ?? line.workOrderId).trim() || null, jobStepId: String(data.get(`jobStepId-${index}`) ?? line.jobStepId).trim() || null, remark: String(data.get(`remark-${index}`) ?? line.remark).trim() || null };
      });
      const created = await requestJson<{ id: string }>("/api/inventory/documents", jsonInit({ documentType: type, documentDate: new Date().toISOString(), purpose, lines: payloadLines }));
      const files = data.getAll("attachments").filter((file): file is File => file instanceof File && file.size > 0);
      for (const file of files) { const upload = new FormData(); upload.set("file", file); upload.set("entityType", "INVENTORY_DOCUMENT"); upload.set("entityId", created.id); await requestJson("/api/attachments/upload", { method: "POST", body: upload }); }
      toast.success(`Inventory request saved as draft${files.length ? ` with ${files.length} attachment(s)` : ""}`); onSaved();
    } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to save request"); }
  }
  return <Card><CardHeader><CardTitle className="text-base">New inventory request</CardTitle></CardHeader><CardContent><form className="space-y-5" onSubmit={save}><div className="grid gap-3 sm:grid-cols-2"><div><Label htmlFor="documentType">Document Type</Label><select id="documentType" value={type} onChange={(event) => { const next = event.target.value as typeof type; setType(next); setReceiptSources({}); if (next === "ISSUE") lines.forEach((draftLine, lineIndex) => void loadReceiptSources(lineIndex, draftLine.stockItemId, draftLine.sourceLocationId, next)); }} className="wo-input mt-1"><option value="ISSUE">Issue</option><option value="RECEIPT">Receipt</option><option value="TRANSFER">Transfer</option></select></div><Field name="purpose" label="Purpose" required /></div><div className="space-y-3">{lines.map((line, index) => <div key={index} className="rounded-xl border bg-slate-50 p-4"><div className="mb-3 flex items-center justify-between"><strong className="text-sm">Line {index + 1}</strong>{lines.length > 1 && <Button type="button" size="sm" variant="ghost" onClick={() => setLines((current) => current.filter((_, lineIndex) => lineIndex !== index))}>Remove</Button>}</div><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><div><Label htmlFor={`stockItemId-${index}`}>Stock Item</Label><select id={`stockItemId-${index}`} value={line.stockItemId} onChange={(event) => { const next = event.target.value; updateLine(index, "stockItemId", next); updateLine(index, "sourceReceiptLineId", ""); void loadReceiptSources(index, next, line.sourceLocationId); }} required className="wo-input mt-1"><option value="">Select item…</option>{refs.items.map((item) => <option key={item.id} value={item.id}>{item.code} — {item.name}</option>)}</select></div><Field name={`requestedQuantity-${index}`} label="Quantity" type="number" required defaultValue={line.requestedQuantity} /><div><Label htmlFor={`sourceLocationId-${index}`}>Source Location</Label><select id={`sourceLocationId-${index}`} value={line.sourceLocationId} onChange={(event) => { const next = event.target.value; updateLine(index, "sourceLocationId", next); updateLine(index, "sourceReceiptLineId", ""); void loadReceiptSources(index, line.stockItemId, next); }} required={type !== "RECEIPT"} disabled={type === "RECEIPT"} className="wo-input mt-1"><option value="">Select location…</option>{refs.locations.map((location) => <option key={location.id} value={location.id}>{location.code} — {location.name}</option>)}</select></div>{type === "ISSUE" && <div><Label htmlFor={`sourceReceiptLineId-${index}`}>Source Receipt</Label><select id={`sourceReceiptLineId-${index}`} value={line.sourceReceiptLineId} onChange={(event) => updateLine(index, "sourceReceiptLineId", event.target.value)} required className="wo-input mt-1" disabled={sourceLoading[index] || !line.stockItemId || !line.sourceLocationId}><option value="">{sourceLoading[index] ? "Loading Receipt sources…" : "Select posted Receipt…"}</option>{(receiptSources[index] ?? []).map((source) => <option key={source.id} value={source.id}>{source.documentNumber} · line {source.lineNumber} · available {source.availableQuantity}</option>)}</select></div>}<div><Label htmlFor={`destinationLocationId-${index}`}>Destination Location</Label><select id={`destinationLocationId-${index}`} value={line.destinationLocationId} onChange={(event) => updateLine(index, "destinationLocationId", event.target.value)} required={type !== "ISSUE"} disabled={type === "ISSUE"} className="wo-input mt-1"><option value="">Select location…</option>{refs.locations.map((location) => <option key={location.id} value={location.id}>{location.code} — {location.name}</option>)}</select></div>{type === "RECEIPT" && <><div><Label htmlFor={`vendorId-${index}`}>Vendor</Label><select id={`vendorId-${index}`} value={line.vendorId} onChange={(event) => updateLine(index, "vendorId", event.target.value)} className="wo-input mt-1"><option value="">Not specified</option>{refs.vendors.map((vendor) => <option key={vendor.id} value={vendor.id}>{vendor.code} — {vendor.name}</option>)}</select></div><Field name={`receiptAmount-${index}`} label="Receipt amount / มูลค่ารับเข้า" type="number" required defaultValue={line.receiptAmount} /><Field name={`expectedDeliveryDate-${index}`} label="Expected Delivery" type="date" defaultValue={line.expectedDeliveryDate} /><Field name={`actualDeliveryDate-${index}`} label="Actual Delivery" type="date" defaultValue={line.actualDeliveryDate} /></>}<Field name={`workOrderId-${index}`} label="Work Order reference" defaultValue={line.workOrderId} /><Field name={`jobStepId-${index}`} label="Job Step reference" defaultValue={line.jobStepId} /><div className="sm:col-span-2"><Field name={`remark-${index}`} label="Line remark" defaultValue={line.remark} /></div></div></div>)}</div><div className="flex flex-wrap gap-2"><Button type="button" variant="outline" onClick={() => setLines((current) => [...current, blankLine()])}>Add another line</Button><label className="flex min-h-10 cursor-pointer items-center rounded-lg border bg-white px-3 text-sm font-semibold">Attachments<input name="attachments" type="file" multiple accept="image/jpeg,image/png,image/webp,application/pdf,text/plain,text/csv,application/zip,.doc,.docx,.xls,.xlsx" className="ml-2 max-w-48 text-xs" /></label><Button type="submit">Save Draft</Button></div></form></CardContent></Card>;
}

function ReportWorkspace({ kind }: { kind: "balances" | "movements" | "transactions" }) {
  const [data, setData] = useState<{ balances?: Array<{ id: string; stockItem: Item; location: Location; quantityOnHand: string; availableQuantity: string; movingAverageCost: string | null; inventoryValue: string | null }>; movements?: Movement[]; documents?: Document[] } | null>(null); const endpoint = kind === "balances" ? "/api/inventory/balances?pageSize=200" : kind === "movements" ? "/api/inventory/movements?pageSize=200" : "/api/inventory/documents?pageSize=100"; const load = () => void requestJson<typeof data>(endpoint).then(setData).catch((error) => toast.error(error.message)); useEffect(load, [endpoint]); if (!data) return <State message="Loading report…" retry={load} />;
  if (kind === "balances") return <TableShell><thead className="border-b bg-slate-50 text-xs text-slate-500"><tr>{["Stock Item", "Location", "On-hand", "Available", "Moving average", "Inventory value"].map((head) => <th key={head} className="px-4 py-3 font-semibold">{head}</th>)}</tr></thead><tbody className="divide-y">{(data.balances ?? []).map((balance) => <tr key={balance.id}><td className="px-4 py-4"><strong>{balance.stockItem.code}</strong><span className="block text-xs text-slate-500">{balance.stockItem.name}</span></td><td className="px-4 py-4">{balance.location.code}</td><td className="px-4 py-4 tabular-nums">{balance.quantityOnHand}</td><td className="px-4 py-4 tabular-nums">{balance.availableQuantity}</td><td className="px-4 py-4 tabular-nums">{money(balance.movingAverageCost)}</td><td className="px-4 py-4 tabular-nums">{money(balance.inventoryValue)}</td></tr>)}</tbody></TableShell>;
  if (kind === "transactions") return <TableShell><thead className="border-b bg-slate-50 text-xs text-slate-500"><tr>{["Document", "Type", "Requester", "Date", "Lines", "Status", "Print"].map((head) => <th key={head} className="px-4 py-3 font-semibold">{head}</th>)}</tr></thead><tbody className="divide-y">{(data.documents ?? []).map((document) => <tr key={document.id}><td className="px-4 py-4 font-mono font-bold text-blue-700">{document.documentNumber}</td><td className="px-4 py-4">{label(document.documentType)}</td><td className="px-4 py-4">{document.requesterName}</td><td className="px-4 py-4 text-xs">{date(document.documentDate)}</td><td className="px-4 py-4">{document.lines.length}</td><td className="px-4 py-4"><Status value={document.status} /></td><td className="px-4 py-4"><a className="text-xs font-semibold text-blue-700 hover:underline" href={`/api/inventory/documents/${document.id}/print`} target="_blank" rel="noreferrer">Print</a></td></tr>)}</tbody></TableShell>;
  return <TableShell><thead className="border-b bg-slate-50 text-xs text-slate-500"><tr>{["Posted", "Movement", "Document", "Source Receipt", "Stock Item", "Location", "In", "Out", "After"].map((head) => <th key={head} className="px-4 py-3 font-semibold">{head}</th>)}</tr></thead><tbody className="divide-y">{(data.movements ?? []).map((movement) => <tr key={movement.id}><td className="px-4 py-4 text-xs">{date(movement.postedAt)}</td><td className="px-4 py-4"><Status value={movement.movementType} /></td><td className="px-4 py-4 font-mono">{movement.documentNumber ?? "—"}</td><td className="px-4 py-4 font-mono text-xs">{movement.sourceReceiptDocumentNumber ?? "—"}</td><td className="px-4 py-4">{movement.stockItem.code}</td><td className="px-4 py-4">{movement.location.code}</td><td className="px-4 py-4 tabular-nums text-emerald-700">{movement.quantityIn}</td><td className="px-4 py-4 tabular-nums text-red-700">{movement.quantityOut}</td><td className="px-4 py-4 tabular-nums">{movement.quantityAfter}</td></tr>)}</tbody></TableShell>;
}

function CountWorkspace({ permissions }: { permissions: Permissions }) {
  const [counts, setCounts] = useState<Array<{ id: string; countNumber: string; countType: string; status: string; lines: Array<{ stockItem: Item; location: Location; systemQuantity: string; countedQuantity: string | null }> }>>([]); const [showForm, setShowForm] = useState(false); const canCreate = permissions.includes("INVENTORY_COUNT_MANAGE"); const load = () => void requestJson<{ counts: typeof counts }>("/api/inventory/counts").then((data) => setCounts(data.counts)).catch((error) => toast.error(error.message)); useEffect(load, []);
  return <ReferenceLoader>{(refs) => <div className="space-y-4"><div className="flex gap-2">{canCreate && <Button onClick={() => setShowForm((value) => !value)}><Plus className="size-4" />New Stock Count</Button>}<Button variant="outline" onClick={load}><RefreshCw className="size-4" />Refresh</Button></div>{showForm && <CountForm refs={refs} onSaved={() => { setShowForm(false); load(); }} />}{counts.length === 0 ? <State message="No stock counts found." /> : <TableShell><thead className="border-b bg-slate-50 text-xs text-slate-500"><tr>{["Count", "Type", "Lines", "System", "Counted", "Status", "Action"].map((head) => <th key={head} className="px-4 py-3 font-semibold">{head}</th>)}</tr></thead><tbody className="divide-y">{counts.map((count) => <tr key={count.id}><td className="px-4 py-4 font-mono font-bold text-blue-700">{count.countNumber}</td><td className="px-4 py-4">{label(count.countType)}</td><td className="px-4 py-4">{count.lines.length}</td><td className="px-4 py-4">{count.lines.reduce((sum, line) => sum + Number(line.systemQuantity), 0)}</td><td className="px-4 py-4">{count.lines.reduce((sum, line) => sum + Number(line.countedQuantity ?? 0), 0)}</td><td className="px-4 py-4"><Status value={count.status} /></td><td className="px-4 py-4"><div className="flex flex-wrap gap-2">{canCreate && ["COUNTING", "RETURNED"].includes(count.status) && <Button size="sm" onClick={() => void requestJson(`/api/inventory/counts/${count.id}/actions`, jsonInit({ action: "SUBMIT" })).then(() => { toast.success("Stock count submitted"); load(); }).catch((error) => toast.error(error.message))}>Submit</Button>}<a className="rounded-md border px-2 py-1 text-xs font-semibold text-blue-700 hover:bg-blue-50" href={`/api/inventory/counts/${count.id}/print`} target="_blank" rel="noreferrer">Print</a></div></td></tr>)}</tbody></TableShell>}</div>}</ReferenceLoader>;
}

function CountForm({ refs, onSaved }: { refs: { items: Item[]; locations: Location[] }; onSaved: () => void }) { async function save(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = event.currentTarget; try { await requestJson("/api/inventory/counts", jsonInit({ countDate: new Date().toISOString(), cutoffAt: new Date().toISOString(), countType: "CYCLE_COUNT", lines: [{ stockItemId: value(form, "stockItemId"), locationId: value(form, "locationId"), countedQuantity: value(form, "countedQuantity") || null }] })); toast.success("Stock count created"); onSaved(); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to create count"); } } return <Card><CardHeader><CardTitle className="text-base">New stock count</CardTitle></CardHeader><CardContent><form className="grid gap-3 sm:grid-cols-3" onSubmit={save}><div><Label htmlFor="stockItemId">Stock Item</Label><select id="stockItemId" name="stockItemId" required className="wo-input mt-1"><option value="">Select item…</option>{refs.items.map((item) => <option key={item.id} value={item.id}>{item.code} — {item.name}</option>)}</select></div><div><Label htmlFor="locationId">Location</Label><select id="locationId" name="locationId" required className="wo-input mt-1"><option value="">Select location…</option>{refs.locations.map((location) => <option key={location.id} value={location.id}>{location.code} — {location.name}</option>)}</select></div><Field name="countedQuantity" label="Counted Quantity" type="number" required /><div className="sm:col-span-3"><Button type="submit">Start Count</Button></div></form></CardContent></Card>; }

function ApprovalWorkspace() { const [items, setItems] = useState<Approval[]>([]); const [commentId, setCommentId] = useState<string | null>(null); const [comment, setComment] = useState(""); const load = () => void requestJson<{ items: Approval[] }>("/api/inventory/approvals?tab=pending&pageSize=100").then((data) => setItems(data.items)).catch((error) => toast.error(error.message)); useEffect(load, []); async function decide(id: string, action: string) { try { await requestJson(`/api/inventory/approvals/${id}/actions`, jsonInit({ action, comment: comment.trim() || (action === "APPROVE" ? "Approved" : "Review required") })); toast.success(`${label(action)} completed`); setCommentId(null); setComment(""); load(); window.dispatchEvent(new Event("approval-count-changed")); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to decide approval"); } } return <div className="space-y-4"><Card className="border-blue-100 bg-blue-50/60"><CardContent className="flex flex-col gap-3 p-4 text-sm text-blue-950 sm:flex-row sm:items-center sm:justify-between"><span>Inventory approvals are also available in the shared Approval Center with the global pending badge.</span><Button asChild variant="outline"><Link href="/approvals?type=INVENTORY">Open shared Approval Center</Link></Button></CardContent></Card>{items.length === 0 ? <State message="No inventory approval is waiting for you." /> : <TableShell><thead className="border-b bg-slate-50 text-xs text-slate-500"><tr>{["Reference", "Request", "Requester", "Step", "Submitted", "Status", "Action"].map((head) => <th key={head} className="px-4 py-3 font-semibold">{head}</th>)}</tr></thead><tbody className="divide-y">{items.map((item) => <tr key={item.id}><td className="px-4 py-4 font-mono font-bold text-blue-700">{item.referenceNumber}</td><td className="px-4 py-4">{item.title}</td><td className="px-4 py-4">{item.requestedByName}</td><td className="px-4 py-4">{label(item.assignedRole)}</td><td className="px-4 py-4 text-xs">{date(item.requestedAt)}</td><td className="px-4 py-4"><Status value={item.status} /></td><td className="px-4 py-4"><div className="flex flex-wrap gap-2"><Button size="sm" onClick={() => { setCommentId(item.id); setComment(""); }}><CheckCircle2 className="size-3.5" />Review</Button></div>{commentId === item.id && <div className="mt-3 min-w-64 space-y-2"><Input placeholder="Comment required" value={comment} onChange={(event) => setComment(event.target.value)} /><div className="flex gap-2"><Button size="sm" onClick={() => void decide(item.id, "APPROVE")}>Approve</Button><Button size="sm" variant="outline" onClick={() => void decide(item.id, "RETURN")}>Return</Button><Button size="sm" variant="destructive" onClick={() => void decide(item.id, "REJECT")}><XCircle className="size-3.5" />Reject</Button></div></div>}</td></tr>)}</tbody></TableShell>}</div>; }

function StockCardWorkspace() { const [refs, setRefs] = useState<{ items: Item[]; locations: Location[] } | null>(null); const [card, setCard] = useState<{ openingQuantity: string; openingValue: string | null; closingQuantity: string; closingValue: string | null; rows: Movement[]; stockItem: Item | null; location: Location | null } | null>(null); const [filters, setFilters] = useState({ stockItemId: "", locationId: "", from: "", to: "" }); useEffect(() => { Promise.all([requestJson<{ items: Item[] }>("/api/inventory/items?pageSize=100&active=true"), requestJson<{ locations: Location[] }>("/api/inventory/locations?pageSize=100&active=true")]).then(([items, locations]) => setRefs({ items: items.items, locations: locations.locations })).catch((error) => toast.error(error.message)); }, []); async function load(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const form = event.currentTarget; try { const params = new URLSearchParams({ stockItemId: value(form, "stockItemId"), locationId: value(form, "locationId"), from: value(form, "from"), to: value(form, "to") }); setFilters({ stockItemId: String(params.get("stockItemId") ?? ""), locationId: String(params.get("locationId") ?? ""), from: String(params.get("from") ?? ""), to: String(params.get("to") ?? "") }); setCard(await requestJson<typeof card>(`/api/inventory/stock-card?${params}`)); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to load stock card"); } } if (!refs) return <State message="Loading stock card references…" />; const exportQuery = new URLSearchParams(filters).toString(); return <div className="space-y-4"><Card><CardContent className="p-4"><form className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5" onSubmit={load}><div className="lg:col-span-2"><Label htmlFor="stockItemId">Stock Item</Label><select id="stockItemId" name="stockItemId" required className="wo-input mt-1"><option value="">Select item…</option>{refs.items.map((item) => <option key={item.id} value={item.id}>{item.code} — {item.name}</option>)}</select></div><div className="lg:col-span-2"><Label htmlFor="locationId">Location</Label><select id="locationId" name="locationId" required className="wo-input mt-1"><option value="">Select location…</option>{refs.locations.map((location) => <option key={location.id} value={location.id}>{location.code} — {location.name}</option>)}</select></div><Field name="from" label="From" type="date" /><Field name="to" label="To" type="date" /><div className="flex items-end gap-2"><Button type="submit"><BookOpen className="size-4" />Run report</Button>{card && <><a className="rounded-md border px-2 py-2 text-xs font-semibold text-blue-700 hover:bg-blue-50" href={`/api/inventory/stock-card/print?${exportQuery}`} target="_blank" rel="noreferrer">Print / PDF</a><a className="rounded-md border px-2 py-2 text-xs font-semibold text-blue-700 hover:bg-blue-50" href={`/api/inventory/stock-card/print?${exportQuery}&format=csv`}>Excel / CSV</a></>}</div></form></CardContent></Card>{card && <div className="space-y-4"><div className="grid gap-3 sm:grid-cols-4"><Card><CardContent className="p-4"><p className="text-xs text-slate-500">Opening quantity</p><strong className="text-xl">{card.openingQuantity}</strong></CardContent></Card><Card><CardContent className="p-4"><p className="text-xs text-slate-500">Opening value</p><strong className="text-xl">{money(card.openingValue)}</strong></CardContent></Card><Card><CardContent className="p-4"><p className="text-xs text-slate-500">Closing quantity</p><strong className="text-xl">{card.closingQuantity}</strong></CardContent></Card><Card><CardContent className="p-4"><p className="text-xs text-slate-500">Closing value</p><strong className="text-xl">{money(card.closingValue)}</strong></CardContent></Card></div><TableShell><thead className="border-b bg-slate-50 text-xs text-slate-500"><tr>{["Posted", "Movement", "Document", "Source Receipt", "In", "Out", "Running quantity", "Running value"].map((head) => <th key={head} className="px-4 py-3 font-semibold">{head}</th>)}</tr></thead><tbody className="divide-y">{card.rows.map((row) => <tr key={row.id}><td className="px-4 py-4 text-xs">{date(row.postedAt)}</td><td className="px-4 py-4"><Status value={row.movementType} /></td><td className="px-4 py-4 font-mono">{row.documentNumber ?? "—"}</td><td className="px-4 py-4 font-mono text-xs">{row.sourceReceiptDocumentNumber ?? "—"}</td><td className="px-4 py-4 text-emerald-700">{row.quantityIn}</td><td className="px-4 py-4 text-red-700">{row.quantityOut}</td><td className="px-4 py-4">{(row as Movement & { runningQuantity?: string }).runningQuantity ?? row.quantityAfter}</td><td className="px-4 py-4">{money((row as Movement & { runningValue?: string | null }).runningValue)}</td></tr>)}</tbody></TableShell></div>}</div>; }

function ConfigurationWorkspace() { const [settings, setSettings] = useState<Array<{ id: string; settingKey: string; value: string; description: string | null }>>([]); const load = () => void requestJson<{ settings: typeof settings }>("/api/inventory/configuration").then((data) => setSettings(data.settings)).catch((error) => toast.error(error.message)); useEffect(load, []); async function save(settingKey: string, nextValue: string, description: string | null) { try { await requestJson("/api/inventory/configuration", jsonInit({ settingKey, value: nextValue, description }, "PATCH")); toast.success("Configuration updated"); load(); } catch (error) { toast.error(error instanceof Error ? error.message : "Unable to update configuration"); } } return <div className="grid gap-4 lg:grid-cols-2"><Card><CardHeader><CardTitle className="text-base">Inventory policy</CardTitle></CardHeader><CardContent className="space-y-3">{settings.length ? settings.map((setting) => <div key={setting.id} className="flex items-center justify-between gap-4 rounded-xl border p-4"><div><strong>{label(setting.settingKey)}</strong><p className="mt-1 text-xs text-slate-500">{setting.description}</p></div><Button variant={setting.value === "true" ? "default" : "outline"} onClick={() => void save(setting.settingKey, setting.value === "true" ? "false" : "true", setting.description)}>{setting.value === "true" ? "Enabled" : "Disabled"}</Button></div>) : <p className="text-sm text-slate-500">No configuration rows have been created yet.</p>}</CardContent></Card><Card><CardHeader><CardTitle className="text-base">Governance</CardTitle></CardHeader><CardContent className="space-y-2 text-sm leading-6 text-slate-600"><p>Stock balances are projections of posted movement ledger rows. Users cannot edit on-hand quantity directly.</p><p>Issue and Transfer validate available stock again while posting under a row lock. Approval and posting are committed in the same database transaction.</p></CardContent></Card></div>; }

function sectionMeta(section: InventorySection) { return section === "dashboard" ? ["Inventory control tower", "Inventory Dashboard", "Live on-hand, approval, vendor and low-stock signals.", <Boxes key="icon" className="size-5" />] : section === "items" ? ["Inventory master data", "Stock Items", "Maintain stock codes, reorder controls, cost and main location.", <PackageSearch key="icon" className="size-5" />] : section === "locations" ? ["Inventory master data", "Storage Locations", "Plant to bin hierarchy with balance visibility.", <Warehouse key="icon" className="size-5" />] : section === "vendors" ? ["Inventory master data", "Vendors", "Vendor contacts, delivery performance and score history.", <Truck key="icon" className="size-5" />] : section === "on-hand" ? ["Inventory reports", "Stock On-hand", "Current balance projection by stock item and location.", <PackageSearch key="icon" className="size-5" />] : section === "transactions" ? ["Inventory documents", "Inventory Transactions", "Issue, receipt and transfer document register.", <ClipboardCheck key="icon" className="size-5" />] : section === "requests" ? ["Inventory workflow", "My Inventory Requests", "Create, submit and track your issue, receipt and transfer requests.", <FilePlus2 key="icon" className="size-5" />] : section === "counts" ? ["Inventory control", "Stock Count", "Snapshot system quantities, count and route variance for approval.", <ClipboardCheck key="icon" className="size-5" />] : section === "approvals" ? ["Inventory workflow", "Inventory Approvals", "Review sequential inventory approvals with segregation of duties.", <ShieldCheck key="icon" className="size-5" />] : section === "movement" ? ["Inventory reports", "Inventory Movement", "Immutable posted ledger for issue, receipt, transfer and adjustment.", <ArrowLeftRight key="icon" className="size-5" />] : section === "stock-card" ? ["Inventory reports", "Stock Card", "Opening balance, posted movements, running balance and closing value.", <BookOpen key="icon" className="size-5" />] : ["Inventory administration", "Inventory Configuration", "Numbering and stock policy settings.", <Settings key="icon" className="size-5" />]; }

export default function InventoryWorkspace({ section, permissions }: { section: InventorySection; permissions: Permissions }) {
  const meta = sectionMeta(section);
  return <PageContainer className="max-w-[112rem]"><PageHeader eyebrow={meta[0] as string} title={meta[1] as string} description={meta[2] as string} icon={meta[3]} actions={<Button variant="outline" onClick={() => window.location.reload()}><RefreshCw className="size-4" />Refresh</Button>} />{section === "dashboard" && <Dashboard permissions={permissions} />}{section === "items" && <ItemWorkspace permissions={permissions} />}{section === "locations" && <LocationWorkspace permissions={permissions} />}{section === "vendors" && <VendorWorkspace permissions={permissions} />}{section === "on-hand" && <ReportWorkspace kind="balances" />}{section === "transactions" && <ReportWorkspace kind="transactions" />}{section === "requests" && <RequestWorkspace permissions={permissions} />}{section === "counts" && <CountWorkspace permissions={permissions} />}{section === "approvals" && <ApprovalWorkspace />}{section === "movement" && <ReportWorkspace kind="movements" />}{section === "stock-card" && <StockCardWorkspace />}{section === "configuration" && <ConfigurationWorkspace />}</PageContainer>;
}
